import app from 'flarum/admin/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Form from 'flarum/common/components/Form';
import Select from 'flarum/common/components/Select';
import ItemList from 'flarum/common/utils/ItemList';
import Stream from 'flarum/common/utils/Stream';
import { aiPayload, driverLabel, nameIsValid, parseTokens } from '../utils/settings';
import ModelInput from './ModelInput';
const id = field => `flarum-ai-connection-${field}`;
const normaliseUrl = url => (url || '').trim().toLowerCase().replace(/\/+$/, '');

/**
 * Adds or edits a connection on the page. Nothing is stored until the admin
 * saves the page.
 */
export default class EditConnectionModal extends FormModal {
  removeKey = false;
  invalid = null;
  oninit(vnode) {
    super.oninit(vnode);
    const connection = this.attrs.connection;
    this.name = Stream(this.attrs.name || '');
    this.driver = Stream(connection?.driver || aiPayload().drivers[0]);
    this.url = Stream(connection?.url || '');
    this.region = Stream(connection?.region || '');
    this.guardrailId = Stream(connection?.guardrail_id || '');
    this.guardrailVersion = Stream(connection?.guardrail_version || '');
    this.model = Stream(connection?.model || '');
    this.monthlyTokens = Stream(connection?.monthly_tokens ? String(connection.monthly_tokens) : '');
    this.key = Stream(connection?.key || '');
  }
  className() {
    return 'EditConnectionModal Modal--small';
  }
  title() {
    return this.attrs.name ? app.translator.trans('flarum-ai.admin.edit_connection.edit_title', {
      name: this.attrs.name
    }) : app.translator.trans('flarum-ai.admin.edit_connection.add_title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m(Form, null, this.fields().toArray(), m("div", {
      className: "Form-group Form-controls"
    }, m(Button, {
      className: "Button Button--primary",
      type: "submit"
    }, app.translator.trans('flarum-ai.admin.edit_connection.submit_button')))));
  }
  fields() {
    const items = new ItemList();
    const {
      keyOptional,
      urlRequired,
      rules,
      awsSdk
    } = aiPayload();
    const driver = this.driver();
    const byRegion = this.byRegion();
    items.add('name', this.field('name', 'flarum-ai.admin.edit_connection.name_label', 'flarum-ai.admin.edit_connection.name_help',
    // A saved key belongs to its connection's name, so a connection keeps the name it was added with.
    m("input", Object.assign({
      className: "FormControl",
      bidi: this.name,
      disabled: !!this.attrs.name,
      maxlength: 50,
      spellcheck: false
    }, this.fieldAttrs('name')))), 60);
    const options = this.driverOptions();
    items.add('driver', this.field('driver', 'flarum-ai.admin.edit_connection.driver_label', null, m(Select, Object.assign({
      options: options,
      value: driver,
      onchange: this.driver
    }, this.fieldAttrs('driver')))), 50);
    if (!awsSdk) {
      items.add('awsSdk', m("p", {
        className: "helpText EditConnectionModal-awsSdk"
      }, app.translator.trans('flarum-ai.admin.edit_connection.aws_sdk_text')), 45);
    }
    if (byRegion) {
      items.add('region', this.field('region', 'flarum-ai.admin.edit_connection.region_label', 'flarum-ai.admin.edit_connection.region_help', m("input", Object.assign({
        className: "FormControl",
        bidi: this.region,
        placeholder: "eu-central-1",
        spellcheck: false
      }, this.fieldAttrs('region')))), 40);
    } else {
      items.add('url', this.field('url', 'flarum-ai.admin.edit_connection.url_label', urlRequired.includes(driver) ? 'flarum-ai.admin.edit_connection.url_required_help' : 'flarum-ai.admin.edit_connection.url_optional_help', m("input", Object.assign({
        className: "FormControl",
        type: "url",
        bidi: this.url,
        spellcheck: false
      }, this.fieldAttrs('url')))), 40);
    }
    items.add('key', this.keyField(keyOptional.includes(driver)), 30);
    items.add('model', this.field('model', 'flarum-ai.admin.edit_connection.model_label', 'flarum-ai.admin.edit_connection.model_help', this.attrs.lists && this.listsSavedModels() ? m(ModelInput, {
      id: id('model'),
      value: this.model(),
      maxlength: rules.modelMaxLength,
      connection: this.attrs.listedAs ?? null,
      lists: this.attrs.lists,
      oninput: this.model
    }) : m("input", Object.assign({
      className: "FormControl",
      bidi: this.model,
      maxlength: rules.modelMaxLength,
      spellcheck: false
    }, this.fieldAttrs('model')))), 20);
    items.add('monthlyTokens', this.field('monthlyTokens', 'flarum-ai.admin.edit_connection.monthly_tokens_label', 'flarum-ai.admin.edit_connection.monthly_tokens_help', m("input", Object.assign({
      className: "FormControl",
      type: "number",
      min: "1",
      step: "1",
      inputmode: "numeric",
      bidi: this.monthlyTokens
    }, this.fieldAttrs('monthlyTokens')))), 10);
    if (driver === 'bedrock') {
      items.add('guardrail', this.field('guardrail', 'flarum-ai.admin.edit_connection.guardrail_label', 'flarum-ai.admin.edit_connection.guardrail_help', m("div", {
        className: "EditConnectionModal-guardrail"
      }, m("input", Object.assign({
        className: "FormControl",
        bidi: this.guardrailId,
        placeholder: app.translator.trans('flarum-ai.admin.edit_connection.guardrail_id_placeholder'),
        spellcheck: false
      }, this.fieldAttrs('guardrail'))), m("input", {
        className: "FormControl",
        bidi: this.guardrailVersion,
        placeholder: "DRAFT",
        spellcheck: false,
        "aria-label": app.translator.trans('flarum-ai.admin.edit_connection.guardrail_version_label')
      }))), 5);
    }
    return items;
  }

  /**
   * The providers to choose from: those the page offers, and the one the
   * connection was saved with, so a Bedrock connection can still be changed
   * or removed after the AWS SDK it needs is taken away.
   */
  driverOptions() {
    const options = {};
    const saved = this.attrs.connection?.driver;
    aiPayload().drivers.forEach(name => options[name] = driverLabel(name));
    if (saved && !(saved in options)) options[saved] = driverLabel(saved);
    return options;
  }

  /**
   * Whether the provider is reached by region, not address.
   */
  byRegion() {
    return aiPayload().regionRequired.includes(this.driver());
  }
  field(field, label, help, control, extra) {
    return m("div", {
      className: "Form-group"
    }, m("label", {
      for: id(field)
    }, app.translator.trans(label)), !!help && m("div", {
      className: "helpText",
      id: id(field) + '-help'
    }, app.translator.trans(help)), control, extra);
  }

  /**
   * Whether the models listed for the saved connection are this one's: it
   * still has the provider, address and key it was saved with.
   */
  listsSavedModels() {
    const saved = this.attrs.connection;
    return !!this.attrs.listedAs && !!saved && this.driver() === saved.driver && (
    // Only the field the provider uses counts, whatever was typed in the other.
    this.byRegion() ? this.region().trim() === (saved.region || '') : normaliseUrl(this.url()) === normaliseUrl(saved.url)) && !this.key().trim() && !this.removeKey;
  }
  fieldAttrs(field) {
    return {
      id: id(field),
      'aria-invalid': this.invalid === field ? 'true' : undefined
    };
  }
  keyField(optional) {
    const savedKey = this.savedKeyApplies();
    const dropped = !!this.attrs.connection?.hasKey && this.attrs.connection.key === undefined && !savedKey;
    return this.field('key', 'flarum-ai.admin.edit_connection.key_label', dropped ? 'flarum-ai.admin.edit_connection.key_dropped_text' : this.driver() === 'bedrock' ? 'flarum-ai.admin.edit_connection.key_bedrock_help' : optional ? 'flarum-ai.admin.edit_connection.key_optional_help' : null, m("input", Object.assign({
      className: "FormControl",
      type: "password"
      // Keeps the browser from filling in the admin's own password.
      ,
      autocomplete: "new-password",
      bidi: this.key,
      placeholder: savedKey && !this.removeKey ? app.translator.trans('flarum-ai.admin.edit_connection.key_saved_placeholder') : '',
      spellcheck: false
    }, this.fieldAttrs('key'))), savedKey && (this.removeKey ? m("div", {
      className: "helpText"
    }, app.translator.trans('flarum-ai.admin.edit_connection.key_removed_text')) : m(Button, {
      className: "Button Button--link",
      onclick: () => this.removeKey = true
    }, app.translator.trans('flarum-ai.admin.edit_connection.remove_key_button'))));
  }

  /**
   * Whether the saved key will still be used: only with the provider and API
   * URL it was saved for, as the server checks.
   */
  savedKeyApplies() {
    const connection = this.attrs.connection;
    return !!connection?.hasKey && connection.key === undefined && connection.driver === this.driver() &&
    // A provider reached by region has no address, whatever was typed before switching to it.
    normaliseUrl(this.byRegion() ? '' : connection.url) === normaliseUrl(this.byRegion() ? '' : this.url()) && (this.byRegion() ? this.region().trim() : '') === (connection.region || '');
  }

  /**
   * The first problem with the form, checked as the server would, so the
   * admin can fix it here, next to the field.
   */
  validate() {
    const name = this.name().trim();
    const driver = this.driver();
    const {
      keyOptional,
      urlRequired,
      rules
    } = aiPayload();
    const region = this.region().trim();
    const guardrailId = this.guardrailId().trim();
    if (!nameIsValid(name)) return {
      field: 'name',
      message: 'flarum-ai.admin.connections.name_invalid_message'
    };
    if (!this.attrs.name && this.attrs.takenNames.includes(name)) return {
      field: 'name',
      message: 'flarum-ai.admin.edit_connection.name_taken_message'
    };
    if (!this.url().trim() && urlRequired.includes(driver)) return {
      field: 'url',
      message: 'flarum-ai.admin.connections.url_required_message'
    };
    if (this.byRegion() && !new RegExp(rules.regionPattern).test(region)) {
      return {
        field: 'region',
        message: region ? 'flarum-ai.admin.connections.region_invalid_message' : 'flarum-ai.admin.connections.region_required_message'
      };
    }
    if (driver === 'bedrock' && guardrailId && (!new RegExp(rules.guardrailPattern).test(guardrailId) || !new RegExp(rules.guardrailVersionPattern).test(this.guardrailVersion().trim() || 'DRAFT'))) {
      return {
        field: 'guardrail',
        message: 'flarum-ai.admin.connections.guardrail_invalid_message'
      };
    }
    if (!this.key().trim() && (this.removeKey || !this.savedKeyApplies()) && !keyOptional.includes(driver)) {
      return {
        field: 'key',
        message: 'flarum-ai.admin.connections.key_required_message'
      };
    }
    if (parseTokens(this.monthlyTokens()) === false) return {
      field: 'monthlyTokens',
      message: 'flarum-ai.admin.connections.tokens_invalid_message'
    };
    return null;
  }
  onsubmit(e) {
    e.preventDefault();
    const name = this.name().trim();
    const problem = this.validate();
    this.invalid = problem?.field ?? null;
    if (problem) {
      this.alertAttrs = {
        type: 'error',
        content: app.translator.trans(problem.message, {
          name
        })
      };

      // Once the alert and the field's state have been drawn.
      setTimeout(() => document.getElementById(id(problem.field))?.focus());
      return;
    }
    const connection = {
      driver: this.driver()
    };
    const url = this.byRegion() ? '' : this.url().trim();
    const region = this.byRegion() ? this.region().trim() : '';
    const guardrailId = this.driver() === 'bedrock' ? this.guardrailId().trim() : '';
    const guardrailVersion = this.guardrailVersion().trim();
    const model = this.model().trim();
    const monthlyTokens = parseTokens(this.monthlyTokens());
    const key = this.key().trim();
    if (url) connection.url = url;
    if (region) connection.region = region;
    if (model) connection.model = model;
    if (monthlyTokens) connection.monthly_tokens = monthlyTokens;
    if (guardrailId) connection.guardrail_id = guardrailId;
    if (guardrailId && guardrailVersion) connection.guardrail_version = guardrailVersion;

    // Left without a key, the connection keeps the saved one, if it still applies.
    if (key) {
      connection.key = key;
    } else if (this.removeKey) {
      connection.key = '';
    } else {
      connection.hasKey = this.savedKeyApplies();
    }
    this.attrs.onsave(name, connection);
    this.hide();
  }
}
flarum.reg.add('flarum-ai', 'admin/components/EditConnectionModal', EditConnectionModal);